});
test('products expose spec fields', () => {
  if (b.products.length === 0) return;
  const p = b.products[0];
  ['product_key','sku_id','product_name','primary_image_url',
   'asmo_material_number','aramco_material_number','product_type','material_type',
   'seller_details','moq','price','currency','sold_by','supplier_count',
   'contract_indicator','category_ids'].forEach(k => expect(p).to.have.property(k));
  expect(p).to.not.have.property('material_id');
  expect(p).to.not.have.property('lead_time');
  expect(p.category_ids).to.be.an('array');
  expect(p.contract_indicator).to.be.a('boolean');
  expect(p.seller_details).to.be.an('array');
});
test('seller_details expose spec fields', () => {
  const p = b.products[0];
  if (!p || !p.seller_details.length) return;
  const s = p.seller_details[0];
  ['seller_id','seller_name','lead_time','unit_type','price','moq','currency'].forEach(k => expect(s).to.have.property(k));
  if (s.lead_time != null) expect(s.lead_time).to.be.a('number');
  expect(p.supplier_count).to.eql(p.seller_details.length);
});

